def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[7] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 7:
                color = grid[r][c]
                neighbors = sum(
                    0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color
                    for rr in range(r - 1, r + 2)
                    for cc in range(c - 1, c + 2)
                    if (rr, cc) != (r, c)
                )
                if neighbors == 0:
                    rr, cc = r, c
                    while rr < h and cc < w:
                        out[rr][cc] = color
                        rr += 1
                        cc += 1
    return out
